INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "", 0, 1, "カリン", 0, 1, 1, 0, 60000, 1);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", "", 0, 1, "", 0, 2, 0, 1, 60000, 2);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 1, "", 0, 2, 0, 1, 60000, 3);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", "", 0, 2, "", 0, 2, 0, 1, 60000, 4);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", "", 0, 1, "", 0, 2, 0, 2, 60000, 5);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", "", 0, 1, "", 0, 2, 0, 2, 60000, 6);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", "", 0, 2, "", 0, 2, 0, 2, 60000, 7);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", "", 0, 1, "", 0, 2, 0, 3, 60000, 8);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", "", 0, 1, "", 0, 2, 0, 3, 60000, 9);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 1, "", 0, 2, 0, 3, 60000, 10);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 1, "", 0, 2, 0, 3, 60000, 11);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", "", 0, 2, "", 0, 2, 0, 3, 60000, 12);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", "", 0, 1, "", 0, 2, 0, 4, 60000, 13);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", "", 0, 1, "", 0, 2, 0, 4, 60000, 14);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", "", 0, 1, "", 0, 2, 0, 4, 60000, 15);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 0, 1, "", 0, 2, 0, 4, 60000, 16);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 0, 2, "", 0, 2, 0, 4, 60000, 17);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "", 0, 0, "カリン", 0, 3, 2, 0, 60000, 18);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "", 0, 0, "カリン", 7, 3, 3, 0, 60000, 19);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101201, "キミと出会ってもう\n1年もたつんだね！\nう～ん、いつも\n寝てばっかりだから、", "", 0, 0, "ハツネ", 1, 0, 1, 0, 80001, 20);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101201, "少しでも\n寝る時間を減らして\nキミと一緒にいる\n時間増やしたいなぁ♪", "", 0, 0, "ハツネ", 1, 0, 2, 0, 80001, 21);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103801, "あなたと知り合ってから\nもう1年…\n時がたつのは\n早いですね", "", 0, 0, "シオリ", 1, 1, 1, 0, 80001, 22);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103801, "来年も、\n一緒にいられたら…\nうれしいな", "", 0, 0, "シオリ", 1, 1, 2, 0, 80001, 23);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103601, "あなたと一緒にいるようになって、\nもう1年ですか…", "", 0, 0, "キョウカ", 2, 0, 1, 0, 80001, 24);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103601, "最初の頃よりも、頼もしく\nなりましたね。私はどうですか？\n成長していますか？", "", 0, 0, "キョウカ", 2, 0, 2, 0, 80001, 25);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102001, "おにいちゃんとあってから、\n1年たったよ～！", "", 0, 0, "ミミ", 2, 1, 1, 0, 80001, 26);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102001, "ミミね、おにいちゃんと\nいっぱい遊べてたのしかったな～♪\nこれからもずっと\nいっしょにいてね～！", "", 0, 0, "ミミ", 2, 1, 2, 0, 80001, 27);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100401, "にいちゃんがミソギのイタズラに\n引っかかり続けてもう1年かぁ", "", 0, 0, "ミソギ", 2, 2, 1, 0, 80001, 28);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100401, "…これからもいっぱいミソギと\n遊んでね、にいちゃん！", "", 0, 0, "ミソギ", 2, 2, 2, 0, 80001, 29);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101001, "もう王子はんと会うてから\n1年ぐらいたつそうどすえ\n早いもんやなあ", "", 0, 0, "マホ", 3, 0, 1, 0, 80001, 30);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101001, "このままやと、\nうちもあっという間に\n干からびてしまいそうどすえ\nなーんてな。うふふ", "", 0, 0, "マホ", 3, 0, 2, 0, 80001, 31);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104401, "お主と会って早1年じゃな\nこれからも存分に尽くすがよい", "", 0, 0, "イリヤ", 3, 1, 1, 0, 80001, 32);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104401, "わらわもたまには、お主の献身に\n報いてやらぬでもない♪", "", 0, 0, "イリヤ", 3, 1, 2, 0, 80001, 33);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101701, "もう、キミと出会って結構な時間が\nたつさ～。でも、私たちの旅は\nまだまだ始まったばかりさ～！", "", 0, 0, "カオリ", 3, 2, 1, 0, 80001, 34);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101701, "これからも、どうぞよろしく\nお願いするさ～！", "", 0, 0, "カオリ", 3, 2, 2, 0, 80001, 35);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102801, "あんたと出会ってからもうそんなに\nたつのね～", "", 0, 0, "サレン", 4, 0, 1, 0, 80001, 36);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102801, "あっという間だったって感じるほど\n楽しかったわ！\nこれからも一緒に頑張りましょ！", "", 0, 0, "サレン", 4, 0, 2, 0, 80001, 37);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102501, "出会ってから1年間、ずっと\nご迷惑をかけっぱなしで、\nすみません…", "", 0, 0, "スズメ", 4, 1, 1, 0, 80001, 38);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102501, "これからはもっと頑張りますから\n見ていてくださいね\nできれば…\n今までよりも、私の近くで♪", "", 0, 0, "スズメ", 4, 1, 2, 0, 80001, 39);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104601, "振り返れば、今までいろんなことが\nあったにゃあ…", "", 0, 0, "タマキ", 5, 0, 1, 0, 80001, 40);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104601, "これからも、二人でたくさんの\n思い出をがっぽり作っていく\nにゃー！", "", 0, 0, "タマキ", 5, 0, 2, 0, 80001, 41);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104801, "キミとの師弟関係も、\nもう1年なのね…\nでもキミに教えることは、", "", 0, 0, "ミフユ", 5, 1, 1, 0, 80001, 42);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104801, "まだまだいっぱいあるわ\nこれからも、\nしっかりついて来てね！", "", 0, 0, "ミフユ", 5, 1, 2, 0, 80001, 43);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103201, "あなたさまと出会ってもう1年…", "", 0, 0, "アキノ", 6, 0, 1, 0, 80001, 44);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103201, "光陰矢のごとし、とはまさに\nこのことですわ。…思い出は決して\nお金では買えませんわね", "", 0, 0, "アキノ", 6, 0, 2, 0, 80001, 45);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103401, "ダメな私を1年間も見捨てないで\nくれて、本当にありがとう", "", 0, 0, "ユカリ", 6, 1, 1, 0, 80001, 46);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103401, "情けないところいっぱいみせるかも\nしれないけど、これからも一緒に\nいてくれると、うれしいな", "", 0, 0, "ユカリ", 6, 1, 2, 0, 80001, 47);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (107101, "オマエと出会ってもう1年か\nまさかこのワタシの結婚相手に\nなろうとはな…", "", 0, 0, "クリスティーナ", 7, 0, 1, 0, 80001, 48);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (107101, "ともかくこれからも\n愉しませてくれよ☆", "", 0, 0, "クリスティーナ", 7, 0, 2, 0, 80001, 49);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104701, "君と出会ってからもう1年か。\n以前と比べて私の表情もいくらか\n柔らかくなった気がするんだが、\nどうだろう？", "", 0, 0, "ジュン", 7, 1, 1, 0, 80001, 50);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104701, "見えないから分からないって？\nそれもそうだな…", "", 0, 0, "ジュン", 7, 1, 2, 0, 80001, 51);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103701, "もう1年たったみたいだね\nあなたをからかってばかりだった\nけど、楽しかった♪", "", 0, 0, "トモ", 8, 0, 1, 0, 80001, 52);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103701, "これからもよろしくね！", "", 0, 0, "トモ", 8, 0, 2, 0, 80001, 53);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100501, "出会って、もう1年たっちゃった\nんスね。なんだか意外ッス", "", 0, 0, "マツリ", 8, 1, 1, 0, 80001, 54);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100501, "毎日楽しくて、あっという間に過ぎ\nちゃったみたいなんスよね\nこれからも一緒に悪と戦うッス！", "", 0, 0, "マツリ", 8, 1, 2, 0, 80001, 55);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100701, "オマエと会って1年なの！\n全然成仏もできなかったし、", "", 0, 0, "ミヤコ", 9, 0, 1, 0, 80001, 56);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100701, "生き返りもしなかったけど、\nすごく楽しかったの～♪\nオマエとプリンがあれば、\nミヤコはハッピーなの～♪", "", 0, 0, "ミヤコ", 9, 0, 2, 0, 80001, 57);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103101, "あなたと出会って1年なんですね\nでも、私の占いでは、私とあなたは", "", 0, 0, "シノブ", 9, 1, 1, 0, 80001, 58);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (103101, "来年も再来年も一緒にいるようです\nふふ、よろしくお願いしますね", "", 0, 0, "シノブ", 9, 1, 2, 0, 80001, 59);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100901, "貴様が閃光のシグルドとして覚醒し\nもう1年か…。これからも我らの\n長き戦いに終わりはないが、", "", 0, 0, "アンナ", 10, 0, 1, 0, 80001, 60);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100901, "それでも貴様となら…\n添い遂げる覚悟はできているぞ！", "", 0, 0, "アンナ", 10, 0, 2, 0, 80001, 61);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101301, "君と出会ってもう1年だって！\n早いねー！", "", 0, 0, "ナナカ", 10, 1, 1, 0, 80001, 62);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101301, "これからも最強のバディタッグで\n大活躍だー！\n頼りにしてるよ、相棒！", "", 0, 0, "ナナカ", 10, 1, 2, 0, 80001, 63);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105101, "1年たつのって、あっという間ね\nまだまだ君の知らない部分が\nたくさんあるし…", "", 0, 0, "ミツキ", 11, 0, 1, 0, 80001, 64);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105101, "これからも、いろんなところを\n調べさせてね？", "", 0, 0, "ミツキ", 11, 0, 2, 0, 80001, 65);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105601, "お前さんと出会ってもう1年か\n助太刀するつもりが", "", 0, 0, "ルカ", 11, 1, 1, 0, 80001, 66);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105601, "逆に助けられたりもしたね\nこれからもよろしく頼むよ！", "", 0, 0, "ルカ", 11, 1, 2, 0, 80001, 67);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102701, "早いものですわね、あなた様と\nお会いして、もう1年…", "", 0, 0, "エリコ", 11, 2, 1, 0, 80001, 68);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102701, "あなた様といると、時があっと\nいう間に過ぎてしまいます\n時間を止める研究をしなくては\nいけませんね…", "", 0, 0, "エリコ", 11, 2, 2, 0, 80001, 69);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102301, "お兄ちゃんと会ってから、もう、\n1年なんだね。私、少しは\nお姉ちゃんっぽくなったかな？", "", 0, 0, "アヤネ", 12, 0, 1, 0, 80001, 70);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102301, "あ、ぷうきちもお兄ちゃんっぽく\nなったよね？", "", 0, 0, "アヤネ", 12, 0, 2, 0, 80001, 71);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104201, "あなたと出会って、\nもう1年がたったんですね…\nこれからもそばにいて、", "", 0, 0, "チカ", 12, 1, 1, 0, 80001, 72);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104201, "私のことを見守ってください\nできることなら、ずっと…", "", 0, 0, "チカ", 12, 1, 2, 0, 80001, 73);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102101, "お兄ちゃんと出会って1年かぁ\n私、相変わらずダメダメで…", "", 0, 0, "クルミ", 12, 2, 1, 0, 80001, 74);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (102101, "で、でもこれからもずっと…\n一緒にいたいなぁ…", "", 0, 0, "クルミ", 12, 2, 2, 0, 80001, 75);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104901, "再会してちょうど1年だね\nお祝いにごちそう作ってきたよ～♪\n特製ケーキと、お寿司と、", "", 0, 0, "シズル", 13, 0, 1, 0, 80001, 76);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (104901, "ハンバーグと、カレーと、\nシチューと、あ、隠しきれない隠し\n味は、お姉ちゃんの愛情だよ！", "", 0, 0, "シズル", 13, 0, 2, 0, 80001, 77);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101101, "お兄ちゃんと再会して、もう1年\nなんですね。\n会えなかった時を思うと、", "", 0, 0, "リノ", 13, 1, 1, 0, 80001, 78);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (101101, "信じられないくらい幸せな1年\nでした！もう絶対、私から離れ\nないでくださいね♪", "", 0, 0, "リノ", 13, 1, 2, 0, 80001, 79);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100201, "騎士クンと出会ってから今まで、\nいろんなことがあったよね\n楽しいこと、ドキドキしたこと…", "", 0, 0, "ユイ", 14, 0, 1, 0, 80001, 80);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100201, "そんな日々をこれからも、\nず、ずっと一緒に…\n過ごしていきたいな…！", "", 0, 0, "ユイ", 14, 0, 2, 0, 80001, 81);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100101, "騎士くんと出会って、まだ1年しか\nたってないんだ！？", "", 0, 0, "ヒヨリ", 14, 1, 1, 0, 80001, 82);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100101, "なんかもうずっと一緒にいる気が\nするなぁ…えへへ。これからの\n1年もまたよろしくねっ！\n騎士くん！", "", 0, 0, "ヒヨリ", 14, 1, 2, 0, 80001, 83);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100301, "初めてキミに出会って1年…\n随分見違えたね私もキミも、\n更に強くなっていく…", "", 0, 0, "レイ", 14, 2, 1, 0, 80001, 84);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (100301, "キミに背中を預けられる日が、\n早くきますように", "", 0, 0, "レイ", 14, 2, 2, 0, 80001, 85);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "1年もわたしのことを、忘れない\nでいてくれて、ありがとうござい\nます！", "", 0, 0, "ペコリーヌ", 15, 0, 1, 0, 80001, 86);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "これからもずっと、覚えていて\nくださいね！", "", 0, 0, "ペコリーヌ", 15, 0, 2, 0, 80001, 87);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "こうして1年も、主さまのおそばに\n置いていただけて、とても光栄\nです。どうかこれからも、", "", 0, 0, "コッコロ", 15, 1, 1, 0, 80001, 88);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "末永く主さまをお世話させて\nください。わたくしは、ずっと\n主さまのガイド役でいたいのです", "", 0, 0, "コッコロ", 15, 1, 2, 0, 80001, 89);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "1年か、まっさかこんなに長い\n付き合いになるなんてね～\nでも…わりと楽しい1年だったかも", "", 0, 0, "キャル", 15, 2, 1, 0, 80001, 90);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "だから、もうしばらくあんたに\n付き合ってやるわよ喜びなさい！", "", 0, 0, "キャル", 15, 2, 2, 0, 80001, 91);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (112101, "新しい年のはじめに、\nおみくじはいかがでしょうか？\nよい運勢であるほど、\n沢山プレゼントが貰えますよ♪", "", 0, 1, "スズメ", 0, 1, 1, 0, 60001, 92);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", "", 0, 1, "", 0, 2, 0, 1, 60001, 93);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 1, "", 0, 2, 0, 1, 60001, 94);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", "", 0, 1, "", 0, 2, 0, 1, 60001, 95);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", "", 0, 1, "", 0, 2, 0, 1, 60001, 96);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", "", 0, 2, "", 0, 2, 0, 1, 60001, 97);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", "", 0, 1, "", 0, 2, 0, 2, 60001, 98);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", "", 0, 1, "", 0, 2, 0, 2, 60001, 99);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", "", 0, 1, "", 0, 2, 0, 2, 60001, 100);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", "", 0, 1, "", 0, 2, 0, 2, 60001, 101);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", "", 0, 2, "", 0, 2, 0, 2, 60001, 102);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", "", 0, 1, "", 0, 2, 0, 3, 60001, 103);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", "", 0, 1, "", 0, 2, 0, 3, 60001, 104);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 1, "", 0, 2, 0, 3, 60001, 105);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 1, "", 0, 2, 0, 3, 60001, 106);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", "", 0, 1, "", 0, 2, 0, 3, 60001, 107);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", "", 0, 1, "", 0, 2, 0, 3, 60001, 108);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", "", 0, 2, "", 0, 2, 0, 3, 60001, 109);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", "", 0, 1, "", 0, 2, 0, 4, 60001, 110);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", "", 0, 1, "", 0, 2, 0, 4, 60001, 111);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", "", 0, 1, "", 0, 2, 0, 4, 60001, 112);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 0, 1, "", 0, 2, 0, 4, 60001, 113);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 0, 1, "", 0, 2, 0, 4, 60001, 114);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", "", 0, 1, "", 0, 2, 0, 4, 60001, 115);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 0, 2, "", 0, 2, 0, 4, 60001, 116);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (112101, "おみくじの結果はいかがでしたか？\n新たに始まる一日が、\nあなたにとってよい日になりますように\n明日もお待ちしていますね♪", "", 0, 0, "スズメ", 0, 3, 2, 0, 60001, 117);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (112101, "おみくじ、楽しんで頂けましたか？\nあなたの新しい年が\n素晴らしいものになるよう、\n心からお祈りしますね", "", 0, 0, "スズメ", 7, 3, 3, 0, 60001, 118);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "ヒューヒュー♪\nドンドンパフパフー♪", "", 0, 0, "ペコリーヌ", 1, 0, 1, 0, 80003, 119);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ひゅーひゅー\nどんどんぱふぱふー\nでございます", "", 0, 0, "コッコロ", 1, 1, 1, 0, 80003, 120);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "さぁ、キャルさまもご一緒に\nどんどんぱふぱふいたしましょう", "", 0, 0, "コッコロ", 1, 1, 2, 0, 80003, 121);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "え？　ちょっと\nいきなりなにっ？", "", 0, 0, "キャル", 1, 2, 1, 0, 80003, 122);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ドンドンパフパフってなんなの？\nあたしにも分かるように\nちゃんと説明しなさいっての！", "", 0, 0, "キャル", 1, 2, 2, 0, 80003, 123);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "実はですねキャルちゃん！\nもうすぐわたしたちにとっての\n大切な節目──", "", 0, 0, "ペコリーヌ", 1, 0, 2, 0, 80003, 124);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "『プリンセスコネクト！\nRe:Dive』\n2.5周年なんですよ！\nやばいですね☆", "", 0, 0, "ペコリーヌ", 1, 0, 3, 0, 80003, 125);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ですからその日に向けて\n今から気分を盛り上げているのです", "", 0, 0, "コッコロ", 1, 1, 3, 0, 80003, 126);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ああ、そういえば\nそんな時期だっけ\nって言っても、もう少し先じゃない\n気が早いんじゃないの？", "", 0, 0, "キャル", 1, 2, 3, 0, 80003, 127);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "いいえ、キャルさま\nこういったお祝いは準備から\n楽しむものでございます\nそうですよね、ペコリーヌさま", "", 0, 0, "コッコロ", 1, 1, 4, 0, 80003, 128);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "その通りです♪　というわけで！\nカウントダウンの始まりですよ！\nみんなで一緒に2.5周年に向けて\n盛り上がっていきましょー☆", "", 0, 0, "ペコリーヌ", 1, 0, 4, 0, 80003, 129);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ド、ドンドンパフパフ～\nって何言わせんのよ！\nまったくもう、浮かれちゃってさ", "", 0, 0, "キャル", 1, 2, 4, 0, 80003, 130);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ふふ。キャルさまもワクワクして\nおいでのようですね\nそれでは主さま。大切な記念日まで\nどうぞご期待くださいませ", "", 0, 0, "コッコロ", 1, 1, 5, 0, 80003, 131);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "記念日を盛り上げるったって\n一体どうしたらいいのよ？\nあたし、そういうの\n苦手なんだけど…", "", 0, 0, "キャル", 2, 0, 5, 0, 80003, 132);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "あら、キャルさん\nどうかなさいましたか？\n何かお困りのようですけど", "", 0, 0, "カリン", 2, 1, 1, 0, 80003, 133);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "げっ…カリンじゃない\nなんでもないわよ！", "", 0, 0, "キャル", 2, 0, 6, 0, 80003, 134);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "そうなのですか？\nキャルさんのことですからてっきり\n2.5周年をどう盛り上げたら\nいいか悩んでいるのかと…", "", 0, 0, "カリン", 2, 1, 2, 0, 80003, 135);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "分かってんじゃないのよ！？\nいっ、いや、違うけどね！\nあたしは別にそんなことで\n悩んでないわよっ？", "", 0, 0, "キャル", 2, 0, 7, 0, 80003, 136);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "ふふっ…\nこういう時は、真心を込めて\n気持ちをそのまま口にしたら\nいいのではないでしょうか？", "", 0, 0, "カリン", 2, 1, 3, 0, 80003, 137);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "気持ちを、ねぇ\nそれが一番難しいんじゃない…\nそもそも、あたしは記念日とか\n別にどうだっていいし", "", 0, 0, "キャル", 2, 0, 8, 0, 80003, 138);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "…まあ、ペコリーヌもコロ助も\nやけに楽しそうだったから…\nこういうお祭り騒ぎみたいなのも\nたまにはいいかな、とは思うけど", "", 0, 0, "キャル", 2, 0, 9, 0, 80003, 139);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "なるほどなるほど～\nキャルさんは【美食殿】で祝う\n2.5周年を心から楽しみに\nしている、ということですね！", "", 0, 0, "カリン", 2, 1, 4, 0, 80003, 140);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "はぁ！？\nどこ聞いたらそうなるのよ！\nあたしは別に楽しみになんか…！", "", 0, 0, "キャル", 2, 0, 10, 0, 80003, 141);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "キャルさんの心からの想い\nみなさんにも伝わったでしょうか？\n私も2.5周年が楽しみです！\n以上、カリンがお伝えしました！", "", 0, 0, "カリン", 2, 1, 5, 0, 80003, 142);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "心からの想いって何なのよ！？\n勝手に人の言葉を\n捻じ曲げんじゃないわよ！\nこのくそ眼鏡ーーーっ！", "", 0, 0, "キャル", 2, 0, 11, 0, 80003, 143);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ペコリーヌさま、もうすぐ\n記念日でございますね\nこういった節目というのは\n感慨深いものでございます", "", 0, 0, "コッコロ", 3, 0, 6, 0, 80003, 144);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "色んな思い出が蘇ってきますね！\n楽しい出来事が\nいっぱいありました♪", "", 0, 0, "ペコリーヌ", 3, 1, 5, 0, 80003, 145);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい、そうでございますね\n主さまも【美食殿】の活動の他にも\nいろんなご経験をされたと\n聞いておりますよ", "", 0, 0, "コッコロ", 3, 0, 7, 0, 80003, 146);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "たしか…ランドソルで話題沸騰と\nなっていた、魔法少女なるものに\nお会いになられたとか", "", 0, 0, "コッコロ", 3, 0, 8, 0, 80003, 147);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "魔法少女って、あの美味しくって\n栄養たっぷりの大ヒット商品\n『魔法少女ソーセージ』の箱に\n描いてある女の子のことですか！？", "", 0, 0, "ペコリーヌ", 3, 1, 6, 0, 80003, 148);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あのソーセージ\n美味しいんですよね～♪\nわたしもたっくさん食べてますよ！", "", 0, 0, "ペコリーヌ", 3, 1, 7, 0, 80003, 149);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "あとは、牧場に素敵な温泉が\n出来たとか…", "", 0, 0, "コッコロ", 3, 0, 9, 0, 80003, 150);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "牧場ですか！？　温泉につかって\nチーズもオツですね～♪　考えた\nだけでよだれが出ちゃいそうです！\nやばいですね☆", "", 0, 0, "ペコリーヌ", 3, 1, 8, 0, 80003, 151);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ペコリーヌさま\n言ってるそばからよだれが…\n今お拭きしますね。ふき、ふき", "", 0, 0, "コッコロ", 3, 0, 10, 0, 80003, 152);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "えへへ、ありがとうございます\nコッコロちゃん！", "", 0, 0, "ペコリーヌ", 3, 1, 9, 0, 80003, 153);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "それにしても、主さまは\n【美食殿】の一員として様々な\n美食と出会われていたのですね\nわたくし、感服いたしました", "", 0, 0, "コッコロ", 3, 0, 11, 0, 80003, 154);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "これからもたくさん冒険をして\nめいっぱい美食を\n味わい尽くしましょうね！", "", 0, 0, "ペコリーヌ", 3, 1, 10, 0, 80003, 155);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "2.5周年カウントダウン♪\nキャルちゃんキャルちゃん！\nわくわくしますね☆", "", 0, 0, "ペコリーヌ", 4, 0, 11, 0, 80003, 156);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あぁもう、うるさいわね～\nまだまだ先でしょ？\nちょっとは落ち着きなさいよ", "", 0, 0, "キャル", 4, 1, 12, 0, 80003, 157);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "キャルちゃんだって最近\nソワソワしてるじゃないですか～\nさっきもご機嫌そうに鼻歌とか\n歌ってましたよね？", "", 0, 0, "ペコリーヌ", 4, 0, 12, 0, 80003, 158);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "なっ…！　き、聞いてたの！？\nじゃない、歌ってないわよ！？\nあんたいい加減なこと言うと\nぶっ殺すわよ！？", "", 0, 0, "キャル", 4, 1, 13, 0, 80003, 159);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "えっへへ～♪\nわたしは最近のキャルちゃんが\nもっともっと大好きですよ♪\nすごく積極的になりましたよね！", "", 0, 0, "ペコリーヌ", 4, 0, 13, 0, 80003, 160);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "…積極的？\nなんの話よ？", "", 0, 0, "キャル", 4, 1, 14, 0, 80003, 161);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "またまた～♪\nアイドルを目指そうとしたこと\n忘れちゃったんですか？", "", 0, 0, "ペコリーヌ", 4, 0, 14, 0, 80003, 162);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "ムーサの町で\nきゃるきゃる～ん☆　って！", "", 0, 0, "ペコリーヌ", 4, 0, 15, 0, 80003, 163);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あっ…！？　ちちち違うわよっ！\nあれは操られてただけで\nあたしはアイドルなんか\n目指してないっての！！", "", 0, 0, "キャル", 4, 1, 15, 0, 80003, 164);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "本当に本当ですか？\nわたし、キャルちゃんとっても\n乗り気だなって\n思ってたんですけど～", "", 0, 0, "ペコリーヌ", 4, 0, 16, 0, 80003, 165);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "まぁ、悪くはなかったけど…って\nだ、だから目指してないって\n言ってるでしょ！！\nなんてこと思い出させんのよ！？", "", 0, 0, "キャル", 4, 1, 16, 0, 80003, 166);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ああ…ダメだわ…\nもう殺すしかない…\n2.5周年が来る前に\n記憶ごと消し去ってやるー！", "", 0, 0, "キャル", 4, 1, 17, 0, 80003, 167);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "2.5周年まであと10日…\nふ～ん？\n案外早いもんね？", "", 0, 0, "キャル", 5, 0, 18, 0, 80003, 168);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "そうでございますね…\nその日のためにやるべきことは\nまだまだございます\n気を引き締めねばなりません…！", "", 0, 0, "コッコロ", 5, 1, 12, 0, 80003, 169);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "やる気十分ねコロ助…\nそんな気負ってるとしんどいわよ？\nお気楽にやりましょ？", "", 0, 0, "キャル", 5, 0, 19, 0, 80003, 170);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "キャルさま…\nありがとうございます\nキャルさまは本当に\n優しいおかたです", "", 0, 0, "コッコロ", 5, 1, 13, 0, 80003, 171);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "な、なにわけの分かんないこと\n言ってんのよ…\nあたしは優しくなんかないっての", "", 0, 0, "キャル", 5, 0, 20, 0, 80003, 172);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "そんなことはございません\n…あの、実はわたくし\nキャルさまに\nひとつお願いがございまして", "", 0, 0, "コッコロ", 5, 1, 14, 0, 80003, 173);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "お願い？　珍しいわね\nコロ助がそんなこと言うなんて\n…まあ、あたしに出来ることなら\n別にいいけど", "", 0, 0, "キャル", 5, 0, 21, 0, 80003, 174);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ありがとうございます\n実は記念日へ向けて\n『かくし芸』というものを\n用意してみようかと思いまして", "", 0, 0, "コッコロ", 5, 1, 15, 0, 80003, 175);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "かくし芸？", "", 0, 0, "キャル", 5, 0, 22, 0, 80003, 176);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい。きゃるきゃる～ん☆　を\n参考に、ころころ～ん☆　という\nご挨拶を考えてみたのですが\nポーズがうまくいかなくて…", "", 0, 0, "コッコロ", 5, 1, 16, 0, 80003, 177);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "～～！！　ちょっと褒められて\nいい気になって損したわ！！\nふざけんなふざけんな\nふ～ざ～け～ん～な～っ！！", "", 0, 0, "キャル", 5, 0, 23, 0, 80003, 178);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あと９日！　もうすぐですよ♪\nえへへ、楽しみで楽しみで\nごはんが進みますね☆", "", 0, 0, "ペコリーヌ", 6, 0, 17, 0, 80003, 179);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ごはんが進みますね☆\nじゃなーい！\nいくらなんでも食べ過ぎよ！\n記念日、迎えられなくなるわよ！？", "", 0, 0, "キャル", 6, 2, 24, 0, 80003, 180);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "大丈夫ですよキャルさま\n食事はわたくしたちの\n歩んできた道そのもの\nなのですから", "", 0, 0, "コッコロ", 6, 1, 17, 0, 80003, 181);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "さっすがコッコロちゃん\nいいことを言いますね！\nそう、わたしたち\n【美食殿】の活動目的は─", "", 0, 0, "ペコリーヌ", 6, 0, 18, 0, 80003, 182);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "─みんなで楽しく食事をすること\nでしょ？\nあれだけ食べ歩いてきたんだから\n分かってるわよ", "", 0, 0, "キャル", 6, 2, 25, 0, 80003, 183);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい…そうでございますね♪\nそれにしてもわたくしたち\n本当にいろいろなものを\n食べ歩いてきましたね…", "", 0, 0, "コッコロ", 6, 1, 18, 0, 80003, 184);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "そうね…ほんっとうにね…\n毒まみれのニセドラゴンとか\n恐竜…は逃げられちゃったっけ\nあとワニゴ…ワニの魔物とかね", "", 0, 0, "キャル", 6, 2, 26, 0, 80003, 185);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "そして、とうとう本物の\nドラゴンまで相手に\nしちゃったのよね、あたしたちって", "", 0, 0, "キャル", 6, 2, 27, 0, 80003, 186);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "信じられない強さだったわね\nあのドラゴン…やっぱり\n作戦はしっかり立てていかないと\nダメよね", "", 0, 0, "キャル", 6, 2, 28, 0, 80003, 187);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "えへへ…☆\nキャルちゃんが色んなことを\n覚えていてくれて\nうれしいです♪", "", 0, 0, "ペコリーヌ", 6, 0, 19, 0, 80003, 188);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "わたくしも鮮明に覚えておりますよ\n主さまもきっと…♪", "", 0, 0, "コッコロ", 6, 1, 19, 0, 80003, 189);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あったり前でしょ！\n忘れないわよ、あんな滅茶苦茶な\nものばかり食べさせられて！\n…忘れられるわけ、ないじゃない", "", 0, 0, "キャル", 6, 2, 29, 0, 80003, 190);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ねえちょっと、ちょっと待って！？\nカリンから、2.5周年記念の\n生放送に出演してほしいって\n言われたんだけど！", "", 0, 0, "キャル", 7, 0, 30, 0, 80003, 191);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "なんでそういう大事なことを\n急に言うわけ！？\nそんなの聞いてないわよ～！？", "", 0, 0, "キャル", 7, 0, 31, 0, 80003, 192);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "いっぱい人に見られちゃうのよね？\nなんであたしがそんなこと…", "", 0, 0, "キャル", 7, 0, 32, 0, 80003, 193);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あー\nあー\n…声、これで大丈夫かしら？", "", 0, 0, "キャル", 7, 0, 33, 0, 80003, 194);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "聞き取りにくいかもしれないわね…\nもうちょっと明るい方がいいかも\nえっと…こんな感じ？", "", 0, 0, "キャル", 7, 0, 34, 0, 80003, 195);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "オイッスー☆", "", 0, 0, "キャル", 7, 0, 35, 0, 80003, 196);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "……\nいや、ないわ\nいつもどおりが一番ね、うん", "", 0, 0, "キャル", 7, 0, 36, 0, 80003, 197);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "もう、記念の生放送なんて\n超責任重大なやつじゃない…\nもしなにか失敗とかしたら…", "", 0, 0, "キャル", 7, 0, 37, 0, 80003, 198);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ど、どど、どうしよう！？\n緊張してきちゃった…！！", "", 0, 0, "キャル", 7, 0, 38, 0, 80003, 199);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "主さま、わたくし\nペコリーヌさまとキャルさまと共に\n2.5周年を祝う生放送に\n出演する大役を仰せつかりました", "", 0, 0, "コッコロ", 8, 0, 20, 0, 80003, 200);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "多くの方々に\n『プリンセスコネクト！\nRe:Dive』の魅力をお伝えする\n重要な役割でございます", "", 0, 0, "コッコロ", 8, 0, 21, 0, 80003, 201);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "わたくし、全身全霊をもって\n生放送に取り組みたいと\n思っております", "", 0, 0, "コッコロ", 8, 0, 22, 0, 80003, 202);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ですが、もしかしたら\nセリフを噛んでしまったり\n段取りを間違えてしまったり\nするかもしれません…", "", 0, 0, "コッコロ", 8, 0, 23, 0, 80003, 203);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "そのようなことがないよう\n練習はしっかりしておかなくては\nまずはこちらから…", "", 0, 0, "コッコロ", 8, 0, 24, 0, 80003, 204);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "オイッスー☆", "", 0, 0, "コッコロ", 8, 0, 25, 0, 80003, 205);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "先ほどキャルさまが練習されて\nいるのをお見かけしたので\nわたくしもと思いまして…\nいかがでしょうか？", "", 0, 0, "コッコロ", 8, 0, 26, 0, 80003, 206);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "良い感じ、ですか？\n…ふふ、ありがとうございます\n主さまのあたたかいお言葉があれば\nわたくしは百人力でございます", "", 0, 0, "コッコロ", 8, 0, 27, 0, 80003, 207);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "この大役を無事に成し遂げ\n主さまに素敵な2.5周年を\n迎えていただけるよう…\nわたくし、尽力いたしますね", "", 0, 0, "コッコロ", 8, 0, 28, 0, 80003, 208);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "オイッスー☆", "", 0, 0, "ペコリーヌ", 9, 0, 20, 0, 80003, 209);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "…う～ん、今のはちょっと\n違う感じがしますね\n堅苦しかったかもしれません", "", 0, 0, "ペコリーヌ", 9, 0, 21, 0, 80003, 210);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あと６日で2.5周年ですか…", "", 0, 0, "ペコリーヌ", 9, 0, 22, 0, 80003, 211);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "この年月がオイッスーの\n歴史なんだと思うと\nじ～んとしちゃいます！\nやばいですね☆", "", 0, 0, "ペコリーヌ", 9, 0, 23, 0, 80003, 212);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "生放送で最高のオイッスー☆　を\nみなさんにお届けするために\n頑張らないと！\nそれじゃあもう一度…", "", 0, 0, "ペコリーヌ", 9, 0, 24, 0, 80003, 213);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "オイッスー☆", "", 0, 0, "ペコリーヌ", 9, 0, 25, 0, 80003, 214);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "…うう～ん、どうしてでしょう\nまだ何かが違う気がします…\nもしかしたら\nおなかが空きすぎてるとか？", "", 0, 0, "ペコリーヌ", 9, 0, 26, 0, 80003, 215);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "今さっき食べたばっかりですけど\nおなかが減っては\n良いオイッスー☆　は\n出せませんよね！", "", 0, 0, "ペコリーヌ", 9, 0, 27, 0, 80003, 216);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "そうと決まれば、コッコロちゃんと\nキャルちゃんを誘って\nごはんにしましょう！\n善は急げです！", "", 0, 0, "ペコリーヌ", 9, 0, 28, 0, 80003, 217);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あ、二人が丁度いいところに！\nオイッス～☆　…ああ！！\n今の、今のですよ～♪", "", 0, 0, "ペコリーヌ", 9, 0, 29, 0, 80003, 218);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "なるほど、どんな時も\n自然体が一番ってことですね！\nこの調子で、生放送も\n頑張っちゃいます♪", "", 0, 0, "ペコリーヌ", 9, 0, 30, 0, 80003, 219);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "2.5周年まで残り５日ですが\nその前にもうすぐ生放送ですよ！\nコッコロちゃん\n準備の方はどうですか？", "", 0, 0, "ペコリーヌ", 10, 0, 31, 0, 80003, 220);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい。わたくし、しっかりと\n備えてまいりました\n万事抜かりはございません", "", 0, 0, "コッコロ", 10, 1, 29, 0, 80003, 221);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "おお～すごい自信を感じます…！\nいい生放送になりそうですね☆\n……あれ？　なんだかこの辺り\n揺れていませんか？", "", 0, 0, "ペコリーヌ", 10, 0, 32, 0, 80003, 222);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "…………", "", 0, 0, "キャル", 10, 2, 39, 0, 80003, 223);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "キャルさま？\nお風邪をひかれたんでしょうか\nひどい震えですが…", "", 0, 0, "コッコロ", 10, 1, 30, 0, 80003, 224);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "かかかか風邪じゃないわよ！\nここここれはただ\nななな生放送が楽しみ過ぎて\nワワワワクワクが止まらないだけ！", "", 0, 0, "キャル", 10, 2, 40, 0, 80003, 225);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "大丈夫ですかキャルちゃん！？\nそうだ、これを飲んでください！", "", 0, 0, "ペコリーヌ", 10, 0, 33, 0, 80003, 226);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "きき気がきくじゃない、ありがとっ\nごくっ、んく…ぶはぁっ！？\nちょっと何飲ませたの！？\n辛っ！　苦ぁ！？　甘ぁっ！？", "", 0, 0, "キャル", 10, 2, 41, 0, 80003, 227);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "これは魔物のエキスに薬草に\nその他色んなものを混ぜた\n特製の栄養ドリンクです！", "", 0, 0, "ペコリーヌ", 10, 0, 34, 0, 80003, 228);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "これを飲めば体ぽかぽかで\n元気いっぱいですよ♪", "", 0, 0, "ペコリーヌ", 10, 0, 35, 0, 80003, 229);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "このアホリーヌ！\n風邪じゃないって言ったでしょ！？\nどさくさに紛れて\nそんな恐ろしいもん飲ませんな～！", "", 0, 0, "キャル", 10, 2, 42, 0, 80003, 230);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "キャルさま\n震えが収まっておりますね\nよかったです…\nわたくし、心配いたしました", "", 0, 0, "コッコロ", 10, 1, 31, 0, 80003, 231);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "え？　ああ、ホントね…って\nだから風邪じゃないって\n言ってるのに…\nまあいいわこの際なんでも", "", 0, 0, "キャル", 10, 2, 43, 0, 80003, 232);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "えっへへ～♪　いつも通りの\nキャルちゃんに戻りましたし\n素敵な生放送が出来そうですね！\n今から楽しみです☆", "", 0, 0, "ペコリーヌ", 10, 0, 36, 0, 80003, 233);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "ランドソルのみなさま、こんにちは\n生放送の会場設営を担当しています\n【ギルド管理協会】のカリンです", "", 0, 0, "カリン", 11, 0, 6, 0, 80003, 234);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "【美食殿】のみなさんは\nまもなく始まる生放送に向けて\n最後の調整のため\n席を外しています", "", 0, 0, "カリン", 11, 0, 7, 0, 80003, 235);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "頑張っている３人の\n邪魔をするわけには\nいきませんので、ご容赦ください", "", 0, 0, "カリン", 11, 0, 8, 0, 80003, 236);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "ですので、本日は私から\n【美食殿】のみなさんの様子を\nお伝えさせていただこうと思います", "", 0, 0, "カリン", 11, 0, 9, 0, 80003, 237);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "まずはペコリーヌさんですが…\n何やら大量のおにぎりを\n食べているようです\nえっと…栄養は大事ですよね", "", 0, 0, "カリン", 11, 0, 10, 0, 80003, 238);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "次にコッコロさんですが\nこちらは発声練習をしています", "", 0, 0, "カリン", 11, 0, 11, 0, 80003, 239);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "一生懸命、小さなお口を開けて\n声を出す姿が応援したくなりますね", "", 0, 0, "カリン", 11, 0, 12, 0, 80003, 240);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "そしてキャルさんは…\nこれは…堂々としたものですね\n何もせず、ただ立ち尽くして…", "", 0, 0, "カリン", 11, 0, 13, 0, 80003, 241);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "あれ？\nもしかして緊張で気を失って…？", "", 0, 0, "カリン", 11, 0, 14, 0, 80003, 242);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "…ええと\n【美食殿】のみなさんは\nやる気十分なようですね！", "", 0, 0, "カリン", 11, 0, 15, 0, 80003, 243);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "３人とも生放送を\nいいものにしようと\n全力で頑張ってくれていますので\nどうかご期待ください", "", 0, 0, "カリン", 11, 0, 16, 0, 80003, 244);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "それでは\nまた明日お会いしましょう♪", "", 0, 0, "カリン", 11, 0, 17, 0, 80003, 245);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "2.5周年まであと３日！\nそして生放送は明日！\nなんかいよいよって感じね…", "", 0, 0, "キャル", 12, 0, 44, 0, 80003, 246);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "３人でい～っぱい練習しましたし\nきっと大丈夫ですよ☆", "", 0, 0, "ペコリーヌ", 12, 2, 37, 0, 80003, 247);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ペコリーヌさまに\n大丈夫と言ってもらえると\nとても心強いですね", "", 0, 0, "コッコロ", 12, 1, 32, 0, 80003, 248);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "信じすぎちゃだめよコロ助\nこいつはなーんにも\n考えてないだけなんだから", "", 0, 0, "キャル", 12, 0, 45, 0, 80003, 249);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "ひどいですよぉキャルちゃ～ん！", "", 0, 0, "ペコリーヌ", 12, 2, 38, 0, 80003, 250);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ふふ。お二人とも\n普段通りの様子で\n安心いたしました", "", 0, 0, "コッコロ", 12, 1, 33, 0, 80003, 251);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "はいっ☆\n生放送でもなんでも\n全力全開、わたしらしく\nぶつかっていくだけです！", "", 0, 0, "ペコリーヌ", 12, 2, 39, 0, 80003, 252);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "そうね。おめでたいことなんだし\nここまで来たんなら\n楽しめるだけ\n楽しむしかないわよね！", "", 0, 0, "キャル", 12, 0, 46, 0, 80003, 253);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "わたくしも、普段よりも心が\n熱くなっております\nこの胸の気持ちをお伝えできるよう\n精一杯努力いたします…！", "", 0, 0, "コッコロ", 12, 1, 34, 0, 80003, 254);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "それでは、いきましょう！\n明日の生放送、絶対に\n成功させましょうね☆", "", 0, 0, "ペコリーヌ", 12, 2, 40, 0, 80003, 255);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "えっと、最初のひと言は…あれ？\nキャルちゃん、わたし\n何て言うんでしたっけ？", "", 0, 0, "ペコリーヌ", 13, 0, 41, 0, 80003, 256);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "は！？\nなにいきなりど忘れしてるの！？\nっていうかあんた、台本は！？", "", 0, 0, "キャル", 13, 2, 47, 0, 80003, 257);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "忘れてきちゃいました☆", "", 0, 0, "ペコリーヌ", 13, 0, 42, 0, 80003, 258);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "忘れてきちゃいました☆\nで済ませられると思ってんの！？\nほら、あたし二冊持ってきたから\nこれ使いなさい！", "", 0, 0, "キャル", 13, 2, 48, 0, 80003, 259);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "マイクとは、こんな高い位置に\nあるものなのですね…！\n背伸びをすれば、何とか…\nう～ん、うぅ～ん…！", "", 0, 0, "コッコロ", 13, 1, 35, 0, 80003, 260);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あぁもう\n少し下げればいいでしょ！？\nこれくらいでいい？\nまったく、世話が焼けるわね…", "", 0, 0, "キャル", 13, 2, 49, 0, 80003, 261);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あれ？\nキャルちゃん、後ろ髪が\nはねちゃってますよ？", "", 0, 0, "ペコリーヌ", 13, 0, 43, 0, 80003, 262);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "え？　うそっ！？\nちゃんと確かめてきたのに！\nどこどこ！？", "", 0, 0, "キャル", 13, 2, 50, 0, 80003, 263);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "キャルさま、動かないで\nくださいまし。今くしで…\nはい、直りましたよ", "", 0, 0, "コッコロ", 13, 1, 36, 0, 80003, 264);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あ、ありがと…はぁ。生放送\n本番までもうすぐなのに\nこんなことしてる場合じゃ\nないわよね", "", 0, 0, "キャル", 13, 2, 51, 0, 80003, 265);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい、時間は残りわずかです\nですが、慌ただしく\n動き回るこの時間も\nなんだか楽しくて…♪", "", 0, 0, "コッコロ", 13, 1, 37, 0, 80003, 266);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "コロ助、あんた…って\nそうじゃなくて！\n胸にジンワリきてる\n暇なんかないでしょ…！？", "", 0, 0, "キャル", 13, 2, 52, 0, 80003, 267);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あはは♪\nキャルちゃんの動きが\nとっても面白いです♪\nやばいですね☆", "", 0, 0, "ペコリーヌ", 13, 0, 44, 0, 80003, 268);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ふふ\nきっと面白い生放送になると\nわたくし、確信しております", "", 0, 0, "コッコロ", 13, 1, 38, 0, 80003, 269);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "絶対絶対、間違いありません！\n見てくれるみなさんが\n笑顔になれる時間を\nお届けしましょう！", "", 0, 0, "ペコリーヌ", 13, 0, 45, 0, 80003, 270);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "そんなの当然でしょ！\n誰が見たって面白いって\n言ってもらえるように\nあれだけ準備したんだから！", "", 0, 0, "キャル", 13, 2, 53, 0, 80003, 271);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "それでは\n記念日直前生放送！\n楽しみにしててくださいね☆", "", 0, 0, "ペコリーヌ", 13, 0, 46, 0, 80003, 272);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "こんにちは\n【ギルド管理協会】のカリンです", "", 0, 0, "カリン", 14, 0, 18, 0, 80003, 273);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "昨日の生放送は\nいかがだったでしょうか？", "", 0, 0, "カリン", 14, 0, 19, 0, 80003, 274);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "たくさんの笑顔と喜びと\nそして驚きを受け取って\nいただけたのではないかと思います", "", 0, 0, "カリン", 14, 0, 20, 0, 80003, 275);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "そしていよいよ\n明日は2.5周年の当日\n待ちに待った記念日を\n迎えることとなります", "", 0, 0, "カリン", 14, 0, 21, 0, 80003, 276);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "【美食殿】のみなさんも\n張り切って様々な準備を\nされていますよ", "", 0, 0, "カリン", 14, 0, 22, 0, 80003, 277);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "【ギルド管理協会】も\n万全のサポート体制で\n協力してまいりたいと思います", "", 0, 0, "カリン", 14, 0, 23, 0, 80003, 278);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "…ふふ、本当に楽しみですね\n【ギルド管理協会】の職員として\nだけではなく、私個人としても…", "", 0, 0, "カリン", 14, 0, 24, 0, 80003, 279);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "この記念日を迎えられることが\n心から楽しみですし\n幸せを感じています", "", 0, 0, "カリン", 14, 0, 25, 0, 80003, 280);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "きっと【美食殿】のみなさんは\nそれ以上に心を弾ませて\nいることでしょう", "", 0, 0, "カリン", 14, 0, 26, 0, 80003, 281);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "それでは\n明日からの2.5周年を\nどうぞ、お楽しみに…♪", "", 0, 0, "カリン", 14, 0, 27, 0, 80003, 282);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "準備はいいですかっ？\n…いっきますよー！", "", 0, 0, "ペコリーヌ", 15, 0, 47, 0, 80003, 283);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "祝！", "", 0, 0, "キャル", 15, 2, 54, 0, 80003, 284);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "2.5周年！", "", 0, 0, "コッコロ", 15, 1, 39, 0, 80003, 285);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "おめでとうございま～す☆", "", 0, 0, "ペコリーヌ", 15, 0, 48, 0, 80003, 286);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "少し前まではまだまだ先じゃない\nとか言ってたけど\n本当にあっという間だったわね", "", 0, 0, "キャル", 15, 2, 55, 0, 80003, 287);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "光陰矢の如し…\nとはこのことでございますね\nでも、今日という日を無事に\n迎えることができて良かったです", "", 0, 0, "コッコロ", 15, 1, 40, 0, 80003, 288);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "コッコロちゃん！　キャルちゃん！\n落ち着くには\nまだ早いですよ！\n盛り上がるのはこれからです☆", "", 0, 0, "ペコリーヌ", 15, 0, 49, 0, 80003, 289);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ほんとあんたはいつも\n全力全開ねー\nでもそうね、記念日なんだし\nパーっといきましょ！", "", 0, 0, "キャル", 15, 2, 56, 0, 80003, 290);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ええ、わたくしも全力全開で\nまいります…！\n主さま、さあ\nどうぞ手を取ってくださいまし…♪", "", 0, 0, "コッコロ", 15, 1, 41, 0, 80003, 291);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あんたもコロ助も、浮かれて\n転ぶんじゃないわよ？\n…仕方ないから、あたしも\n手を繋いであげるわよ", "", 0, 0, "キャル", 15, 2, 57, 0, 80003, 292);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あー！　二人ともずるいです！\nわたしもっ、ギュー♪", "", 0, 0, "ペコリーヌ", 15, 0, 50, 0, 80003, 293);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ちょっ、ペコリーヌ！\nくっつき過ぎよ！", "", 0, 0, "キャル", 15, 2, 58, 0, 80003, 294);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "記念日だから\n平気平気♪\nやばいですね☆", "", 0, 0, "ペコリーヌ", 15, 0, 51, 0, 80003, 295);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "意味分かんないわよ！", "", 0, 0, "キャル", 15, 2, 59, 0, 80003, 296);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ふふ。このめでたき日に\n喜びがあふれておりますね\n主さまは…いかがでしょうか？", "", 0, 0, "コッコロ", 15, 1, 42, 0, 80003, 297);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "喜んでいただけているならば\nわたくしはとてもとても\n幸せでございます", "", 0, 0, "コッコロ", 15, 1, 43, 0, 80003, 298);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "さぁ、2.5周年を\n楽しみ尽くしますよ☆\nまだまだ食べたいものもありますし\nやりたいこともたくさんです！", "", 0, 0, "ペコリーヌ", 15, 0, 52, 0, 80003, 299);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "分かった、分かったから\n引っ張るんじゃないわよ！\n…そんな掴まなくても\nちゃんとついていくから", "", 0, 0, "キャル", 15, 2, 60, 0, 80003, 300);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ペコリーヌさま…キャルさま…\n主さま…共にまいりましょう\nどこまでも…！", "", 0, 0, "コッコロ", 15, 1, 44, 0, 80003, 301);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "はい！　それでは2.5周年\n食べつくしツアーへ！\nそして、その先の未来へ\n向かって出発しましょう！", "", 0, 0, "ペコリーヌ", 15, 0, 53, 0, 80003, 302);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "2.5周年\nありがとうございます！", "105901,45,106001,61", 1, 0, "ペコリーヌ・コッコロ・キャル", 15, 0, 54, 0, 80003, 303);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "", 0, 1, "カリン", 0, 1, 1, 0, 60002, 304);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", "", 0, 1, "", 0, 2, 0, 1, 60002, 305);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 1, "", 0, 2, 0, 1, 60002, 306);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", "", 0, 1, "", 0, 2, 0, 1, 60002, 307);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", "", 0, 1, "", 0, 2, 0, 1, 60002, 308);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", "", 0, 2, "", 0, 2, 0, 1, 60002, 309);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", "", 0, 1, "", 0, 2, 0, 2, 60002, 310);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", "", 0, 1, "", 0, 2, 0, 2, 60002, 311);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", "", 0, 1, "", 0, 2, 0, 2, 60002, 312);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", "", 0, 1, "", 0, 2, 0, 2, 60002, 313);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", "", 0, 2, "", 0, 2, 0, 2, 60002, 314);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", "", 0, 1, "", 0, 2, 0, 3, 60002, 315);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", "", 0, 1, "", 0, 2, 0, 3, 60002, 316);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 1, "", 0, 2, 0, 3, 60002, 317);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", "", 0, 1, "", 0, 2, 0, 3, 60002, 318);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたい焼き！　和菓子パワーで売上アップです！", "", 0, 1, "", 0, 2, 0, 3, 60002, 319);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 1, "", 0, 2, 0, 3, 60002, 320);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかのごとく、色々な事がうまくいきますよ♪", "", 0, 2, "", 0, 2, 0, 3, 60002, 321);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", "", 0, 1, "", 0, 2, 0, 4, 60002, 322);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", "", 0, 1, "", 0, 2, 0, 4, 60002, 323);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", "", 0, 1, "", 0, 2, 0, 4, 60002, 324);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 0, 1, "", 0, 2, 0, 4, 60002, 325);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 0, 1, "", 0, 2, 0, 4, 60002, 326);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", "", 0, 1, "", 0, 2, 0, 4, 60002, 327);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 0, 2, "", 0, 2, 0, 4, 60002, 328);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "", 0, 0, "カリン", 0, 3, 2, 0, 60002, 329);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "", 0, 0, "カリン", 7, 3, 3, 0, 60002, 330);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ささ、シェフィさまはこちらへ…", "", 0, 0, "コッコロ", 1, 4, 1, 0, 80005, 331);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "コッコロさん、どこへ行くの…？\n…え？", "", 0, 0, "シェフィ", 1, 0, 1, 0, 80005, 332);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "『おめでとうございます！\nわ～パチパチー！』\n…という感じでどうですかね！？", "", 0, 0, "ペコリーヌ", 1, 3, 1, 0, 80005, 333);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ではわたくしも\n後ろからクラッカーを鳴らして\n応戦いたします\nああ、当日が待ち遠しいですね", "", 0, 0, "コッコロ", 1, 4, 2, 0, 80005, 334);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "ええと…\n二人とも何をしているの？", "", 0, 0, "シェフィ", 1, 0, 2, 0, 80005, 335);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "シェフィは初めてだもんね\nあの日が近いからって\n予行練習してんのよ\n気が早いわよね～", "", 0, 0, "キャル", 1, 1, 1, 0, 80005, 336);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "あの日…？", "", 0, 0, "シェフィ", 1, 0, 3, 0, 80005, 337);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "その通りです…\nいよいよ記念すべきあの日が\n近づいてきましたよ！", "", 0, 0, "ペコリーヌ", 1, 3, 2, 0, 80005, 338);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "『プリンセスコネクト！\nRe:Dive』3.5周年！", "", 0, 0, "ペコリーヌ", 1, 3, 3, 0, 80005, 339);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "やばいですね☆", "", 0, 0, "カリン", 1, 2, 1, 0, 80005, 340);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "って、なにしれっと\n参加してんのよカリン！", "", 0, 0, "キャル", 1, 1, 2, 0, 80005, 341);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "ふふ、いいじゃないですか\n【ギルド管理協会】として\n私もみなさんと一緒に\nお祝いをさせてください！", "", 0, 0, "カリン", 1, 2, 2, 0, 80005, 342);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "それに…記念日が近づけば\nとっておきの情報を\nお届けしますから♪", "", 0, 0, "カリン", 1, 2, 3, 0, 80005, 343);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "というわけで\n今日からシェフィちゃんも一緒に\nカウントダウンしちゃいましょう！\n3.5周年まで…", "", 0, 0, "ペコリーヌ", 1, 3, 4, 0, 80005, 344);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "えっ！？　ええとええと…！\nあ、あと14日…！", "", 0, 0, "シェフィ", 1, 0, 4, 0, 80005, 345);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "3.5周年まであと13日\n豪華に、そして盛大に\nお祝いしたいですね☆", "", 0, 0, "ペコリーヌ", 2, 3, 5, 0, 80005, 346);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "豪華といえば前にとある貴族さまが\n舞踏会を開かれたそうで\n主さまがそのお手伝いを\nしておりました", "", 0, 0, "コッコロ", 2, 1, 3, 0, 80005, 347);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "そこで美しい所作を学ばれたので\nわたくしも教えていただきました\nしゃなり、しゃなり…\nいかがでしょう？", "", 0, 0, "コッコロ", 2, 1, 4, 0, 80005, 348);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "すっごく上手ですよ☆\nまるでお姫様みたいです\nせっかくなのでわたしも\nしゃなりしゃなり", "", 0, 0, "ペコリーヌ", 2, 3, 6, 0, 80005, 349);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "さすがでございます\nペコリーヌさま", "", 0, 0, "コッコロ", 2, 1, 5, 0, 80005, 350);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "いや、あんたは\nできなきゃダメでしょ\n本物のお姫様なんだし", "", 0, 0, "キャル", 2, 0, 3, 0, 80005, 351);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "しゃなり、しゃなり…\nふふ、案外できるものね", "", 0, 0, "シェフィ", 2, 2, 5, 0, 80005, 352);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "わぁ！\nシェフィちゃん\n姿勢がとってもキレイです♪", "", 0, 0, "ペコリーヌ", 2, 3, 7, 0, 80005, 353);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "さ、次はキャルさまの\n番でございますよ", "", 0, 0, "コッコロ", 2, 1, 6, 0, 80005, 354);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あ、あたしはいいわよ！\nそういうの全然分かんないし…", "", 0, 0, "キャル", 2, 0, 4, 0, 80005, 355);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "大丈夫\nやってみると結構楽しいわよ\nほらほらっ", "", 0, 0, "シェフィ", 2, 2, 6, 0, 80005, 356);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "そ、そこまで言うなら…\nしゃなにゅわきゃあっ！", "", 0, 0, "キャル", 2, 0, 5, 0, 80005, 357);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "いたたた…もぉお～！\nなんであたしがこんな目に～！", "", 0, 0, "キャル", 2, 0, 6, 0, 80005, 358);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "まぁまぁ\n記念日までに練習すれば\nできるようになるかもしれません\nよろしければお教えいたしますよ", "", 0, 0, "コッコロ", 2, 1, 7, 0, 80005, 359);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "よし！\nあんたたちができて\nあたしだけできないのはしゃくだし\nやってやろうじゃないの！！", "", 0, 0, "キャル", 2, 0, 7, 0, 80005, 360);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "3.5周年まであと12日\n記念日当日はもちろんですが\nその日を待つ時間というのも\n心躍ります", "", 0, 0, "コッコロ", 3, 1, 8, 0, 80005, 361);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "分かりますっ！\nどんな特別な料理を食べられるのか\n考えるだけでワクワクしますよね！", "", 0, 0, "ペコリーヌ", 3, 3, 8, 0, 80005, 362);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "特別な料理といえば、お祭りですね\nそういえば主さまは学生として\n聖学祭に参加されたこと\nがあるとか…", "", 0, 0, "コッコロ", 3, 1, 9, 0, 80005, 363);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "聖学祭…って、なにかしら？", "", 0, 0, "シェフィ", 3, 2, 7, 0, 80005, 364);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "聖テレサ女学院の祭典ですよ\n二つのチームが競い合い\n青春を満喫するのが趣旨のようです", "", 0, 0, "コッコロ", 3, 1, 10, 0, 80005, 365);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "それってカルミナの\nサプライズライブがあった\nお祭りよね？\nちょっと見たかったかも…", "", 0, 0, "キャル", 3, 0, 8, 0, 80005, 366);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "カルミナの後の\nライブも好評だったらしいじゃない\n確か、なかよし部\nだったっけ…？", "", 0, 0, "キャル", 3, 0, 9, 0, 80005, 367);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "なかよし部…\n仲が良さそうな名前で\nやばいですね☆", "", 0, 0, "ペコリーヌ", 3, 3, 9, 0, 80005, 368);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "いや、そのまんますぎでしょ…", "", 0, 0, "キャル", 3, 0, 10, 0, 80005, 369);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "聖学祭かぁ…なんだか楽しそうね\nそれになかよし部の人たちも\n気になるわ", "", 0, 0, "シェフィ", 3, 2, 8, 0, 80005, 370);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "それじゃあわたしたちも、\n負けじと仲良くしましょう♪\nほらほらシェフィちゃん、\nぎゅーっ☆　ですよ♪", "", 0, 0, "ペコリーヌ", 3, 3, 10, 0, 80005, 371);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "えっ？　ええ…\nぎゅーっ…？", "", 0, 0, "シェフィ", 3, 2, 9, 0, 80005, 372);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "3.5周年まであと11日！？\nお祝いの準備進んでないんだけど…\nああ～昨日に戻りたいわ…", "", 0, 0, "キャル", 4, 0, 11, 0, 80005, 373);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "そういえばそんな魔道具があるって\n聞いたことがあるわね\n確か、名前はタイムラーベ…", "", 0, 0, "シェフィ", 4, 2, 10, 0, 80005, 374);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "なにそれヤバいわね\nでも本当にあるんだったら\n準備よりももっとやり直したいこと\nたくさんあるんだけど…", "", 0, 0, "キャル", 4, 0, 12, 0, 80005, 375);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "もしや正月の件でしょうか…？\nあの時はお金がなくて\n苦労しましたから", "", 0, 0, "コッコロ", 4, 1, 11, 0, 80005, 376);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "あれはそうね…\nお金を湯水のように使う\nぺコリーヌを止められたら\nあんな苦労をすることもなかったし", "", 0, 0, "キャル", 4, 0, 13, 0, 80005, 377);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "そんなこともありましたね！\nやり直したいといえば\n『きゃるきゃる～ん♪』\nの方かと思いましたよ！", "", 0, 0, "ペコリーヌ", 4, 3, 11, 0, 80005, 378);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "バラすんじゃないわよ\nこのアホリーヌ！\nシェフィはそれ\n知らないんだから！", "", 0, 0, "キャル", 4, 0, 14, 0, 80005, 379);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "こうなったらもう、なんとか\nタイムラーべを探し出して\n今の会話をなかったことに…\nって、どうしたのよシェフィ", "", 0, 0, "キャル", 4, 0, 15, 0, 80005, 380);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "うん…もし、私だったら…\n私が知らないみんなとの時間を\n見てみたいな、って…", "", 0, 0, "シェフィ", 4, 2, 11, 0, 80005, 381);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "シェフィちゃん！　タイムなんとか\nなんかなくても大丈夫ですよ！\n一緒の時間はこれから\nどんどん作ればいいんですから！", "", 0, 0, "ペコリーヌ", 4, 3, 12, 0, 80005, 382);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい、今この瞬間も\n未来にはかけがえのない思い出に\nなっていることでしょう", "", 0, 0, "コッコロ", 4, 1, 12, 0, 80005, 383);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "だからそんな顔しないの\nほら、お祝いの準備、進めるわよ！", "", 0, 0, "キャル", 4, 0, 16, 0, 80005, 384);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "みんな…そうね\n最高のお祝いにして\n最高の思い出にしましょう！", "", 0, 0, "シェフィ", 4, 2, 12, 0, 80005, 385);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "3.5周年まで、あと10日！\nもうすぐですよー！\n楽しみすぎて、やばいですね！", "", 0, 0, "ペコリーヌ", 5, 3, 13, 0, 80005, 386);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "そういえば…たくさんのおもちゃが\n子どもたちを襲うっていう\n騒動もありましたね…\nなんでも勝手に動き出したとか！", "", 0, 0, "ペコリーヌ", 5, 3, 14, 0, 80005, 387);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "学校や孤児院とかに\nちっちゃなおもちゃが乗り込んで\n暴れたみたいですよ！", "", 0, 0, "ペコリーヌ", 5, 3, 15, 0, 80005, 388);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "暴れたって言っても\n所詮はおもちゃじゃない\nどうせちっさいんでしょ？", "", 0, 0, "キャル", 5, 0, 17, 0, 80005, 389);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "だったら魔法で\n全部ぶっ飛ばせばいいじゃない！\n大したことないわよ！", "", 0, 0, "キャル", 5, 0, 18, 0, 80005, 390);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "キャルってば…\n相手は子どもが\n大事にしてる物なのよ…？", "", 0, 0, "シェフィ", 5, 2, 13, 0, 80005, 391);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "乱暴な発言は\nめっ、でございますよ？\n子どもの教育に悪影響を\n与えてしまいますから…", "", 0, 0, "コッコロ", 5, 1, 13, 0, 80005, 392);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "キャルちゃんだって\n意外と猫グッズとか\nたっくさん集めてますよね？\nもしその子たちが暴れたら…？", "", 0, 0, "ペコリーヌ", 5, 3, 16, 0, 80005, 393);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "う、うっさいわね！\n意外とか言うな！\n…ま、まあ確かに正面切って\n魔法でぶっ飛ばせないかもね…", "", 0, 0, "キャル", 5, 0, 19, 0, 80005, 394);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あはは☆\nキャルちゃんのそういうところ\n好きですよ♪", "", 0, 0, "ペコリーヌ", 5, 3, 17, 0, 80005, 395);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "そんなキャルちゃんに猫グッズを\nプレゼントしちゃいますね！\n一部で流行っていた、たい焼き屋の\nおまけフィギュアですよ♪", "", 0, 0, "ペコリーヌ", 5, 3, 18, 0, 80005, 396);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "乱暴に扱ったりしないでくださいね\nひとりでに暴れ出しちゃうかも\nしれませんから！", "", 0, 0, "ペコリーヌ", 5, 3, 19, 0, 80005, 397);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "3.5周年まであと９日\nここでみなさんに\nビックニュースですよ！", "", 0, 0, "カリン", 6, 2, 4, 0, 80005, 398);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "3.5周年を祝う生放送に\n去年と同様【美食殿】の\nみなさんにご出演いただくことが\n決定しましたー！", "", 0, 0, "カリン", 6, 2, 5, 0, 80005, 399);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "…えっ！？", "", 0, 0, "キャル", 6, 1, 20, 0, 80005, 400);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "本当ですか！？\nそれじゃ今から張り切って\n生放送中に食べる魔物料理を\n作らなくちゃですね☆", "", 0, 0, "ペコリーヌ", 6, 3, 20, 0, 80005, 401);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "いや…がんばるところは\nそこじゃないような…\nというか去年も出演してたのね\nすごいじゃない！", "", 0, 0, "シェフィ", 6, 0, 14, 0, 80005, 402);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい。とても緊張しますが\nやりがいのある大役です\n一緒にがんばりましょうね\nシェフィさま", "", 0, 0, "コッコロ", 6, 4, 14, 0, 80005, 403);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "わ、私も出るの！？　でも…\n私も【美食殿】の一人だものね\nそれなら今からしっかり準備をして\nコンディションを整えないと…", "", 0, 0, "シェフィ", 6, 0, 15, 0, 80005, 404);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ふふん♪\n生放送直前のカチコチになった\nシェフィの姿が楽しみだわ！", "", 0, 0, "キャル", 6, 1, 21, 0, 80005, 405);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "去年のキャルちゃんは\n緊張しすぎてずっと震えて\nかわいかったですもんね！\n今年もあの姿が見たいです！", "", 0, 0, "ペコリーヌ", 6, 3, 21, 0, 80005, 406);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ぶっ殺すぞ！？", "", 0, 0, "キャル", 6, 1, 22, 0, 80005, 407);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "というわけで\n『プリンセスコネクト！\nRe:Dive』の魅力を\nお伝えする生放送をお楽しみに♪", "", 0, 0, "カリン", 6, 2, 6, 0, 80005, 408);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "3.5周年まであと８日\nでございますよ\n楽しみですね、主さま", "", 0, 0, "コッコロ", 7, 1, 15, 0, 80005, 409);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "そういえばあんた\n夏休みの宿題は\nきちんとやってるの？", "", 0, 0, "キャル", 7, 0, 23, 0, 80005, 410);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "宿題…学校に通うのも\n楽しいことばかりじゃ\nないのね", "", 0, 0, "シェフィ", 7, 2, 16, 0, 80005, 411);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あれ？　そういえば\n少し前にルーセント学院で\n何かあったような…", "", 0, 0, "ペコリーヌ", 7, 3, 22, 0, 80005, 412);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ああ、始業式の日に\n大捕り物があったって\n話題になってたわね", "", 0, 0, "キャル", 7, 0, 24, 0, 80005, 413);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "夏休みを終わらせないって\n騒いでたっていう話？\nあれ本当なの？\n都市伝説だと思ってたわ", "", 0, 0, "シェフィ", 7, 2, 17, 0, 80005, 414);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "その一件ならよく存じ上げて\nおります。ですから主さま\n次の機会にはわたくしと一緒に\nがんばりましょう", "", 0, 0, "コッコロ", 7, 1, 16, 0, 80005, 415);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "楽しそう…私も一緒にやりたいな\nママ…じゃ、じゃなくて！\nコッコロさん、私もまざっていい？", "", 0, 0, "シェフィ", 7, 2, 18, 0, 80005, 416);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "もちろんでございます\n仲良くお勉強いたしましょう", "", 0, 0, "コッコロ", 7, 1, 17, 0, 80005, 417);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "しれっと教育ママが\n生まれてる…？", "", 0, 0, "キャル", 7, 0, 25, 0, 80005, 418);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "お勉強は大切ですよ！\nキャルちゃんも一緒に\nがんばりましょう！", "", 0, 0, "ペコリーヌ", 7, 3, 23, 0, 80005, 419);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "え～～～～！？", "", 0, 0, "キャル", 7, 0, 26, 0, 80005, 420);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "3.5周年まであと７日〜♪\nふふ～ん♪\nふんふふ～ん♪", "", 0, 0, "キャル", 8, 0, 27, 0, 80005, 421);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "…\nねぇコッコロさん\nキャル、どうしちゃったの？", "", 0, 0, "シェフィ", 8, 2, 19, 0, 80005, 422);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "とてもご機嫌そうに\n鼻歌を歌ってらっしゃいますね\n耳も尻尾もリズミカルに\n揺れて…ノリノリでございます", "", 0, 0, "コッコロ", 8, 1, 18, 0, 80005, 423);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あれはですね！\nカルミナのみなさんの\nサマーライブのチケットが\n手に入ったからなんですよ♪", "", 0, 0, "ペコリーヌ", 8, 3, 24, 0, 80005, 424);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "ええっ！？\nあのライブのチケットって確か\n入手困難だったんじゃ…", "", 0, 0, "シェフィ", 8, 2, 20, 0, 80005, 425);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ふふふふ～ん♪\nしゃいにんぐふゅ～ちゃ～♪", "", 0, 0, "キャル", 8, 0, 28, 0, 80005, 426);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "なるほど…\nキャルさまがあのように\nなってしまうのも頷けますね", "", 0, 0, "コッコロ", 8, 1, 19, 0, 80005, 427);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "…カルミナの\n『Shining Future』\nの中に、シャイニングフューチャー\nって歌詞はなかったはずだけど…", "", 0, 0, "シェフィ", 8, 2, 21, 0, 80005, 428);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ふんふ…はっ！？\nあっ、あんたたち！\nなに人の鼻歌を\n勝手に聞いてるのよ！？", "", 0, 0, "キャル", 8, 0, 29, 0, 80005, 429);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "こっ、これは別に\nカルミナの曲じゃなくて…\nあたしのオリジナルソングよ！\n聞いたらお金取るわよっ！？", "", 0, 0, "キャル", 8, 0, 30, 0, 80005, 430);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "えへへ、キャルちゃん\nカルミナのサマーライブ\n思いっきり楽しみましょうね☆", "", 0, 0, "ペコリーヌ", 8, 3, 25, 0, 80005, 431);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "も～っ！\n生暖かい目で見るな～～！\nぶっ殺すわよ～～～！", "", 0, 0, "キャル", 8, 0, 31, 0, 80005, 432);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "3.5周年まであと６日\n３人も言ってたけど\nあっという間だったわね", "", 0, 0, "シェフィ", 9, 0, 22, 0, 80005, 433);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "…えっ？\n生放送の意気込み！？\n突然なに！？", "", 0, 0, "シェフィ", 9, 0, 23, 0, 80005, 434);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "ええと…\nとにかく失敗しないように\n台本たくさん読んで…\nそれから…", "", 0, 0, "シェフィ", 9, 0, 24, 0, 80005, 435);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "えっ！？\nトラブルがあったら\nどうするのかって！？\nそ、それは…！", "", 0, 0, "シェフィ", 9, 0, 25, 0, 80005, 436);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "とにかく落ち着いて\nスタッフさんの指示を聞いて…", "", 0, 0, "シェフィ", 9, 0, 26, 0, 80005, 437);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "それから、それから…！\nぅ、ぅぅっ…！", "", 0, 0, "シェフィ", 9, 0, 27, 0, 80005, 438);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "―びえぇぇ～んっ！！！", "", 0, 0, "シェフィ", 9, 0, 28, 0, 80005, 439);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "どうされましたか、シェフィさま", "", 0, 0, "コッコロ", 9, 1, 20, 0, 80005, 440);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "ううっ…ひっく…\nママッ…！", "", 0, 0, "シェフィ", 9, 0, 29, 0, 80005, 441);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "よしよし、緊張されてるのですね\nママが傍におりますよ\n主さま、少々お待ちくださいませ", "", 0, 0, "コッコロ", 9, 1, 21, 0, 80005, 442);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "…ふぅ\nシェフィさま\n生放送への意気込み\nお話しできそうですか？", "", 0, 0, "コッコロ", 9, 1, 22, 0, 80005, 443);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "…ううっ\n恥ずかしすぎて\nもう生放送出られない…", "", 0, 0, "シェフィ", 9, 0, 30, 0, 80005, 444);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "主さま\n3.5周年まであと５日\nでございます", "", 0, 0, "コッコロ", 10, 0, 23, 0, 80005, 445);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ですがその前に\n生放送がありますね", "", 0, 0, "コッコロ", 10, 0, 24, 0, 80005, 446);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "…生放送に向けた\n意気込みでございますか？", "", 0, 0, "コッコロ", 10, 0, 25, 0, 80005, 447);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "もちろんわたくしは\n主さまのために\n全身全霊を込めて\n楽しい時間をご提供いたします", "", 0, 0, "コッコロ", 10, 0, 26, 0, 80005, 448);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "…と、意気込んでみましたが\nうまくできるか少し不安です\n声が小さくなったり\n間違えてしまったらどうしようと…", "", 0, 0, "コッコロ", 10, 0, 27, 0, 80005, 449);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ですがわたくしは\n一人ではありません\n【美食殿】のみなさまが\nおります", "", 0, 0, "コッコロ", 10, 0, 28, 0, 80005, 450);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "どんな困難も\nみなさまと一緒なら\n乗り越えられると\nわたくし、確信しております", "", 0, 0, "コッコロ", 10, 0, 29, 0, 80005, 451);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "それに今回はシェフィさまも\nご参加されるわけですし\nママとしてお手本に\nならねばなりませんね", "", 0, 0, "コッコロ", 10, 0, 30, 0, 80005, 452);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "主さま。3.5周年も\n食卓を囲んでいる時のような\n楽しい思い出を\n一緒に作りましょうね", "", 0, 0, "コッコロ", 10, 0, 31, 0, 80005, 453);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "3.5周年まであと４日！\nやばいですね☆", "", 0, 0, "ペコリーヌ", 11, 0, 26, 0, 80005, 454);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "はいはい、やばいわね\nというかもうすぐ生放送だけど\nあんた準備はできてるの？", "", 0, 0, "キャル", 11, 1, 32, 0, 80005, 455);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "ばっちりオイッスー☆　ですよ！\n『王家の装備』も全開です！", "", 0, 0, "ペコリーヌ", 11, 0, 27, 0, 80005, 456);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あとは前回を超える\n最高のオイッスー☆　を\nお届けできるように\n練習あるのみですかね！", "", 0, 0, "ペコリーヌ", 11, 0, 28, 0, 80005, 457);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "キャルちゃんは\nどうなんですか？\nオイッスー☆　を\n毎日ちゃんと練習してますか？", "", 0, 0, "ペコリーヌ", 11, 0, 29, 0, 80005, 458);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "はぁ！？　なんであたしまで\nその変なあいさつを練習しないと\nいけないのよ！", "", 0, 0, "キャル", 11, 1, 33, 0, 80005, 459);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "もしかしてやってないんですか？\nダメですよキャルちゃん！\nシェフィちゃんだってちゃんと\n毎日練習してるのに！", "", 0, 0, "ペコリーヌ", 11, 0, 30, 0, 80005, 460);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "こうなったらわたしがキャルちゃん\nにオイッスー☆　の『オ』から\nしっかり教えてあげないと！", "", 0, 0, "ペコリーヌ", 11, 0, 31, 0, 80005, 461);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "オイッスー☆　の『オ』は\n口を大きく開いて〜\nドラゴンの骨つき肉に\nかぶりつく直前をイメージして〜", "", 0, 0, "ペコリーヌ", 11, 0, 32, 0, 80005, 462);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "だからあたしはやるなんて一言も…", "", 0, 0, "キャル", 11, 1, 34, 0, 80005, 463);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "オイッスー☆", "", 0, 0, "ペコリーヌ", 11, 0, 33, 0, 80005, 464);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "聞きなさいっての！！", "", 0, 0, "キャル", 11, 1, 35, 0, 80005, 465);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "3.5周年まであと３日…\nそして生放送は、明日…", "", 0, 0, "シェフィ", 12, 2, 31, 0, 80005, 466);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "もっと台本を\n読み込んでおかないと…\nあと発声練習も…", "", 0, 0, "シェフィ", 12, 2, 32, 0, 80005, 467);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "おいっす！\n…こうじゃなかったわね\nええと確か…", "", 0, 0, "シェフィ", 12, 2, 33, 0, 80005, 468);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "うう…あんなに練習したのに\nこれじゃみんなに迷惑かけちゃう…", "", 0, 0, "シェフィ", 12, 2, 34, 0, 80005, 469);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "【美食殿】の一員として\n認められるように\n頑張らないといけないのに\nよし、もう一度…", "", 0, 0, "シェフィ", 12, 2, 35, 0, 80005, 470);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "やってますねシェフィちゃん！", "", 0, 0, "ペコリーヌ", 12, 3, 34, 0, 80005, 471);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "なによ、考えることは\nみんな同じってこと？", "", 0, 0, "キャル", 12, 0, 36, 0, 80005, 472);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ふふ。シェフィさま\nよろしければ\n仲間に入れてください\n一緒にやればきっとうまくできます", "", 0, 0, "コッコロ", 12, 1, 32, 0, 80005, 473);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "みんな…もちろんよ！", "", 0, 0, "シェフィ", 12, 2, 36, 0, 80005, 474);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "それじゃ明日の生放送に向けて\n一緒に練習がんばりましょう☆", "", 0, 0, "ペコリーヌ", 12, 3, 35, 0, 80005, 475);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "3.5周年まであと２日と\n迫った本日は…\nいよいよ生放送です！", "", 0, 0, "カリン", 13, 2, 7, 0, 80005, 476);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "【美食殿】のみなさんが\n準備に入られていますので\nそれぞれ繋いでみましょう！\nまずはペコリーヌさんです！", "", 0, 0, "カリン", 13, 2, 8, 0, 80005, 477);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "今日もオイッスー☆\nみんなで一緒に\nオイッスー☆", "", 0, 0, "ペコリーヌ", 13, 3, 36, 0, 80005, 478);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "お手本になるような\n発声練習ですね！\nそれでは続いてコッコロさん", "", 0, 0, "カリン", 13, 2, 9, 0, 80005, 479);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はじめちょろちょろ\nなかぱっぱ～♪\n生放送前にみなさまで\n食卓を囲んで英気を養いましょう", "", 0, 0, "コッコロ", 13, 4, 33, 0, 80005, 480);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "さすが【美食殿】のママですね！\nそしてキャルさんは…", "", 0, 0, "カリン", 13, 2, 10, 0, 80005, 481);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "大丈夫…大丈夫…\nあたしは大丈夫…", "", 0, 0, "キャル", 13, 1, 37, 0, 80005, 482);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "す、すごく震えてますけど\n大丈夫でしょうか…？\nそして今回初参加となる\n期待の新人シェフィさん！", "", 0, 0, "カリン", 13, 2, 11, 0, 80005, 483);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "あうー？", "", 0, 0, "シェフィ", 13, 0, 37, 0, 80005, 484);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "あ…", "105901,34,106001,38,190801,12", 1, 0, "みんな", 13, 4, 37, 0, 80005, 485);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ちょ、ちょっとシェフィ！？\nなに赤ちゃん返りしてん―\nあ痛ぁっ！\n噛んだわこいつーっ！", "", 0, 0, "キャル", 13, 1, 39, 0, 80005, 486);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "シェフィさま\n緊張しすぎて\nしまったのでしょうね…\nおーよしよし…", "", 0, 0, "コッコロ", 13, 4, 35, 0, 80005, 487);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "シェフィちゃん！\nそういう時は手のひらに\n好きな文字を書いて\n食べちゃうといいですよ！", "", 0, 0, "ペコリーヌ", 13, 3, 38, 0, 80005, 488);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "…ええと、現場からは以上です！\n生放送はもうすぐ！\n特別なお知らせもありますので\nどうぞお楽しみに！", "", 0, 0, "カリン", 13, 2, 13, 0, 80005, 489);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "3.5周年の記念日も\nいよいよ明日ね\n…って、あれ？", "", 0, 0, "シェフィ", 14, 2, 38, 0, 80005, 490);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "記念日はこの森へ行きませんか！？\nすっごく美味しいお肉が\nとれるんです☆", "", 0, 0, "ペコリーヌ", 14, 3, 39, 0, 80005, 491);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "うげ、またあの魔物？\nさすがに今度は\n丸焼きとかはやめてよね…\n見た目がヤバすぎるし", "", 0, 0, "キャル", 14, 0, 40, 0, 80005, 492);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ふふ、キャルさまもだいぶ\n魔物肉に慣れてきたようですね\n調理ならばわたくしに\nお任せください♪", "", 0, 0, "コッコロ", 14, 1, 36, 0, 80005, 493);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "みんな、何をしているの？\nなんだか、\n不穏な単語が聞こえたんだけど…", "", 0, 0, "シェフィ", 14, 2, 39, 0, 80005, 494);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "シェフィちゃん！\n明日の食べ尽くしツアーの\n相談をしてたんですよ！", "", 0, 0, "ペコリーヌ", 14, 3, 40, 0, 80005, 495);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "はい。明日は【美食殿】の\n一員となったシェフィさまと一緒に\n初めて記念日を過ごすのですから\n特別なコース料理を用意しませんと", "", 0, 0, "コッコロ", 14, 1, 37, 0, 80005, 496);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "ふふん♪\n猫の毛も逆立つような\nあれこれを食べさせられるから\n覚悟しておいたほうがいいわよ？", "", 0, 0, "キャル", 14, 0, 41, 0, 80005, 497);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "へ、へぇ…", "", 0, 0, "シェフィ", 14, 2, 40, 0, 80005, 498);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "期待しててくださいね！\nシェフィちゃんとあなたに\n『おいちー！』って喜んでもらえる\n最高のごちそうを準備しますから☆", "", 0, 0, "ペコリーヌ", 14, 3, 41, 0, 80005, 499);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "ええと…その…うーんと…\nわ、分かったわ\n私も【美食殿】の一員だもの", "", 0, 0, "シェフィ", 14, 2, 41, 0, 80005, 500);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "それにあなたも一緒みたいだし\n最後までがんばってみるわ…！", "", 0, 0, "シェフィ", 14, 2, 42, 0, 80005, 501);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "それではいつものあれを\nやりましょう！\n準備はいいですかっ？\n…いっきますよー！", "", 0, 0, "ペコリーヌ", 15, 3, 42, 0, 80005, 502);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "祝！", "", 0, 0, "キャル", 15, 1, 42, 0, 80005, 503);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "3.5周年！", "", 0, 0, "コッコロ", 15, 4, 38, 0, 80005, 504);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "おめでとうございます！", "", 0, 0, "シェフィ", 15, 0, 43, 0, 80005, 505);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "この日を迎えられたのも\nあなたが『プリンセスコネクト！\nRe:Dive』を遊んでくれている\nおかげです！", "", 0, 0, "カリン", 15, 2, 14, 0, 80005, 506);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190801, "ということで\nみなさんからあなたへ一言ずつ\n感謝の言葉をどうぞ！", "", 0, 0, "カリン", 15, 2, 15, 0, 80005, 507);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "感謝の言葉ですか？　わたしは\n毎日あなたに感謝してますよ\n【美食殿】の仲間になってくれて…\n一緒にごはんを食べてくれて…", "", 0, 0, "ペコリーヌ", 15, 3, 43, 0, 80005, 508);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "なにより今でもわたしをぺコリーヌ\nって呼んでくれてありがとうござい\nます。これからもわたしはあなたの\nぺコリーヌです！　やばいですね☆", "", 0, 0, "ペコリーヌ", 15, 3, 44, 0, 80005, 509);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "えっ！？　今度はあたし！？\n感謝って…まぁ、そうね…\nあんたにはあたしが\n辛くて苦しい時に助けてもらって…", "", 0, 0, "キャル", 15, 1, 43, 0, 80005, 510);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106001, "でもおかげで色々吹っ切れたわ！\nもしあんたが困ってたら今度は\nあたしが助けてあげるから\nその時はちゃんと言いなさいよ！", "", 0, 0, "キャル", 15, 1, 44, 0, 80005, 511);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "ええと…次は私ね\n実はよく覚えてないのだけど\n空から落ちてきた私を受け止めて\nくれたのはあなたなのでしょう？", "", 0, 0, "シェフィ", 15, 0, 44, 0, 80005, 512);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (106401, "最初に私を見つけてくれたのが\nあなたで良かったって思ってるの\nおかげで私は居場所を見つけたから\nあなたがくれたもの、大切にするわ", "", 0, 0, "シェフィ", 15, 0, 45, 0, 80005, 513);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "では最後にわたくしから…\nわたくしは主さまの元を離れた日…\nこのように記念日をお祝いする\nことは二度とないと思っていました", "", 0, 0, "コッコロ", 15, 4, 39, 0, 80005, 514);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "ですが、主さまはわたくしを\n迎えにきてくださり、今もこうして\nおそばにおいてくださっています\nわたくしにとって毎日が記念日です", "", 0, 0, "コッコロ", 15, 4, 40, 0, 80005, 515);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105901, "わたくしたちの物語は\nまだ続いていきます\nこれからも一緒にページを\n作っていきましょうね", "", 0, 0, "コッコロ", 15, 4, 41, 0, 80005, 516);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "それじゃ\nいつものあれでしめますよ！\nみんなで一緒に、さんはい☆", "", 0, 0, "ペコリーヌ", 15, 3, 45, 0, 80005, 517);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (105801, "これからも\nよろしくおねがいします！", "105901,42,106001,45,106401,46,190801,16", 1, 0, "みんな", 15, 4, 46, 0, 80005, 518);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "", 0, 1, "カリン", 0, 1, 1, 0, 60003, 519);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", "", 0, 1, "", 0, 2, 0, 1, 60003, 520);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 1, "", 0, 2, 0, 1, 60003, 521);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", "", 0, 1, "", 0, 2, 0, 1, 60003, 522);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　精霊も新年の幸福をお祝いしています！　　主さまの笑顔が見られて、わたくしも幸せいっぱいでございます♪", "", 0, 1, "", 0, 2, 0, 1, 60003, 523);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", "", 0, 2, "", 0, 2, 0, 1, 60003, 524);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", "", 0, 1, "", 0, 2, 0, 2, 60003, 525);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", "", 0, 1, "", 0, 2, 0, 2, 60003, 526);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　ラッキーカラーは鮮やかな黄色！　　　　　さらにシマシマのアイテムを持つと、運気倍増らしいッスよ♪", "", 0, 1, "", 0, 2, 0, 2, 60003, 527);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", "", 0, 1, "", 0, 2, 0, 2, 60003, 528);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", "", 0, 2, "", 0, 2, 0, 2, 60003, 529);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", "", 0, 1, "", 0, 2, 0, 3, 60003, 530);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", "", 0, 1, "", 0, 2, 0, 3, 60003, 531);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 0, 1, "", 0, 2, 0, 3, 60003, 532);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", "", 0, 1, "", 0, 2, 0, 3, 60003, 533);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", "", 0, 1, "", 0, 2, 0, 3, 60003, 534);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 0, 1, "", 0, 2, 0, 3, 60003, 535);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", "", 0, 2, "", 0, 2, 0, 3, 60003, 536);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", "", 0, 1, "", 0, 2, 0, 4, 60003, 537);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", "", 0, 1, "", 0, 2, 0, 4, 60003, 538);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", "", 0, 1, "", 0, 2, 0, 4, 60003, 539);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", "", 0, 1, "", 0, 2, 0, 4, 60003, 540);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 0, 1, "", 0, 2, 0, 4, 60003, 541);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", "", 0, 1, "", 0, 2, 0, 4, 60003, 542);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は小吉！　無理は禁物、お家で静かにしていましょう　プロぼっちの私が、お家での過ごし方……教えてあげましょうか？", "", 0, 2, "", 0, 2, 0, 4, 60003, 543);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "", 0, 0, "カリン", 0, 3, 2, 0, 60003, 544);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "", 0, 0, "カリン", 7, 3, 3, 0, 60003, 545);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (190804, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "", 0, 1, "カリン", 0, 1, 1, 0, 60004, 546);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 0, 1, "", 0, 2, 0, 1, 60004, 547);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", "", 0, 1, "", 0, 2, 0, 1, 60004, 548);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　宴でも開きたくなるほどの絶対幸運！\nイメチェンでもしてみるのはどうだ？　ぴょんぴょん、なんてな♪", "", 0, 1, "", 0, 2, 0, 1, 60004, 549);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　ずっと祈り続けていた願いが叶うかも！\nきっとあんたならたどり着けるわ、ハッピーエンドのその先に", "", 0, 1, "", 0, 2, 0, 1, 60004, 550);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", "", 0, 1, "", 0, 2, 0, 1, 60004, 551);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", "", 0, 1, "", 0, 2, 0, 2, 60004, 552);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", "", 0, 2, "", 0, 2, 0, 2, 60004, 553);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　ラッキーワードは「ぴょんぴょん♪」\nおっきな声で一緒に言ってみよ～♪　うさぎさんぴょんぴょ～ん♪", "", 0, 1, "", 0, 2, 0, 2, 60004, 554);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　あなたの趣味がもっと広がるかも！\nかんわゆ～～～いショタと～騎士きゅんもゲット～んふふ～♪", "", 0, 1, "", 0, 2, 0, 2, 60004, 555);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", "", 0, 1, "", 0, 2, 0, 2, 60004, 556);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, "今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", "", 0, 1, "", 0, 2, 0, 3, 60004, 557);
